// Map PipelineInputType / PipelineOutputType values to icon keys
const TYPE_ALIASES: Record<string, string> = {
  INBOUND_EMAIL: "GMAIL",
  CUSTOM_EMAIL: "EMAIL",
  MAILGUN: "GMAIL",
  GOOGLE: "GOOGLE_DRIVE",
  GOOGLE_GMAIL: "GMAIL",
  INBOUND_WHATSAPP: "WHATSAPP",
  CHROME_EXTENSION: "CHROME",
  SLACK_REACTION: "SLACK",
  WEB_QUESTION: "WEB",
};

/** Resolve the raw path + viewBox for a service type (after alias resolution),
 *  for callers that need to render the mark themselves (e.g. as a tiled mask).
 *  Returns null for unknown types. */
export function getServiceIconPath(
  type: string,
): { d: string; viewBox: string } | null {
  const key = TYPE_ALIASES[type] ?? type;
  const icon = ICON_PATHS[key];
  if (!icon) return null;
  return { d: icon.d, viewBox: icon.viewBox ?? "0 0 24 24" };
}

export function ServiceIcon({
  type,
  className = "h-4 w-4",
}: {
  type: string;
  className?: string;
}) {
  const key = TYPE_ALIASES[type] ?? type;
  const icon = ICON_PATHS[key];

  if (!icon) {
    // Fallback: generic plug icon for unknown services
    return (
      <svg
        className={className}
        viewBox="0 0 24 24"
        fill="none"
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
        strokeLinejoin="round"
      >
        <path d="M12 2v6m-4-2v4m8-4v4M8 10h8a2 2 0 0 1 2 2v1a6 6 0 0 1-12 0v-1a2 2 0 0 1 2-2zm4 11v3" />
      </svg>
    );
  }

  const vb = icon.viewBox ?? "0 0 24 24";

  if (icon.fill) {
    return (
      <svg className={className} viewBox={vb} fill="currentColor">
        <path fillRule="evenodd" clipRule="evenodd" d={icon.d} />
      </svg>
    );
  }

  return (
    <svg
      className={className}
      viewBox={vb}
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
    >
      <path d={icon.d} />
    </svg>
  );
}
